<script>
  "use strict";

  const allowance = 270;
  const setupMinutes = 25;
  const pieceMinutes = 4;
  const maxLaborChart = 320;
  const weeks = [
    { orders: 9, pieces: 35, eligible: 5 },
    { orders: 12, pieces: 48, eligible: 8 },
    { orders: 7, pieces: 28, eligible: 3 },
    { orders: 15, pieces: 62, eligible: 10 },
    { orders: 10, pieces: 41, eligible: 6 },
    { orders: 13, pieces: 53, eligible: 7 }
  ];
  const get = (id) => document.getElementById(id);
  const format = new Intl.NumberFormat("en-US");
  const count = (value) => format.format(value);

  function estimate({ orders, pieces, eligible }) {
    const once = pieceMinutes * pieces + setupMinutes;
    return { orders, pieces, eligible, once, twice: once + setupMinutes, friday: orders - eligible };
  }

  function renderHistory() {
    const results = weeks.map(estimate);
    const totals = { orders: 0, pieces: 0, once: 0, twice: 0, eligible: 0, friday: 0 };
    const columns = Object.keys(totals);
    for (const [index, week] of results.entries()) {
      const row = document.createElement("tr");
      row.innerHTML = `<th scope="row">${index + 1}</th>`;
      for (const field of columns) {
        totals[field] += week[field];
        const cell = row.insertCell();
        cell.textContent = count(week[field]);
        if ((field === "once" || field === "twice") && week[field] > allowance) {
          cell.classList.add("over-cell");
          const overage = document.createElement("small");
          overage.textContent = `${week[field] - allowance} over`;
          cell.append(" ", overage);
        }
      }
      row.classList.toggle("over-row", week.twice > allowance);
      get("weeks").append(row);

      const pair = document.createElement("div");
      pair.className = "pair";
      for (const labor of [week.once, week.twice]) {
        const bar = document.createElement("span");
        bar.className = "bar";
        bar.style.setProperty("--height", `${labor / maxLaborChart * 100}%`);
        pair.append(bar);
      }
      get("chart-bars").append(pair);
      const label = document.createElement("span");
      label.textContent = `W${index + 1}`;
      get("chart-labels").append(label);
    }

    get("totals").innerHTML = `<tr><th scope="row">Total</th>${columns.map((field) => `<td>${count(totals[field])}</td>`).join("")}</tr>`;
    get("avg-once").textContent = count(totals.once / weeks.length);
    get("avg-twice").textContent = count(totals.twice / weeks.length);
    get("early-count").textContent = `${count(totals.eligible)} of ${count(totals.orders)}`;
    get("early-percent").textContent = `${(totals.eligible / totals.orders * 100).toFixed(1)}%`;
    const fitsOnce = results.filter((week) => week.once <= allowance).length;
    const fitsTwice = results.filter((week) => week.twice <= allowance).length;
    get("weeks-fit").textContent = fitsOnce === fitsTwice
      ? `${fitsOnce} of ${weeks.length}`
      : `${fitsOnce} / ${fitsTwice}`;
  }

  const fields = [get("pieces"), get("orders"), get("eligible")];
  const [piecesInput, ordersInput, eligibleInput] = fields;

  function updateCalculator() {
    const [pieces, orders, eligible] = fields.map((field) => field.valueAsNumber);
    const error = get("calc-error");
    const output = get("calc-output");
    let invalidFields = fields.filter((field) =>
      !Number.isSafeInteger(field.valueAsNumber) || field.valueAsNumber < 0
    );
    let message = "Enter whole, nonnegative counts in all three fields.";

    if (!invalidFields.length) {
      if (eligible > orders) {
        invalidFields = [eligibleInput];
        message = "Orders by Wednesday noon must be at most the total orders.";
      } else if (pieces < orders || (orders === 0 && pieces > 0)) {
        invalidFields = [piecesInput, ordersInput];
        message = "Each order needs at least one piece. When there are zero orders, enter zero pieces.";
      } else if (!Number.isSafeInteger(pieceMinutes * pieces + 2 * setupMinutes)) {
        invalidFields = [piecesInput];
        message = "Enter a smaller piece count.";
      }
    }

    for (const field of fields) {
      field.setAttribute("aria-invalid", String(invalidFields.includes(field)));
    }
    output.hidden = invalidFields.length > 0;
    error.hidden = !output.hidden;
    error.textContent = output.hidden ? message : "";
    if (output.hidden) return;

    const planned = estimate({ orders, pieces, eligible });
    for (const [prefix, labor] of [["one", planned.once], ["two", planned.twice]]) {
      const remaining = allowance - labor;
      const margin = get(`${prefix}-margin`);
      get(`${prefix}-time`).textContent = `${count(labor)} min`;
      margin.textContent = remaining < 0 ? `${count(-remaining)} min over` : remaining === 0 ? "At allowance" : `${count(remaining)} min spare`;
      margin.classList.toggle("over", remaining < 0);
    }
    get("one-ship").textContent = `Fri: ${count(orders)}`;
    get("two-ship").textContent = `Wed: ${count(eligible)} · Fri: ${count(planned.friday)}`;

    const summary = get("scenario-summary");
    summary.classList.toggle("exception", planned.once > allowance);
    if (orders === 0) {
      summary.textContent = "Skip production. The estimates above include setup only if a run is scheduled.";
    } else if (planned.once > allowance) {
      summary.textContent = "Both schedules exceed 270 minutes. Add labor time or move work before promising shipment.";
    } else if (planned.twice > allowance) {
      summary.textContent = "Run once and ship Friday. A second setup would exceed the weekly allowance.";
    } else if (eligible === 0) {
      summary.textContent = "Run once. The second setup would move zero orders to Wednesday.";
    } else {
      const orderText = eligible === 1 ? "1 order" : `${count(eligible)} orders`;
      summary.textContent = `Run twice if ready. ${orderText} could ship Wednesday instead of Friday.`;
    }
  }

  renderHistory();
  updateCalculator();
  get("calculator").addEventListener("input", updateCalculator);
  get("calculator").addEventListener("submit", (event) => event.preventDefault());
  get("print-button").addEventListener("click", () => window.print());
</script>
</body>
</html>
